e('uus','Undifferentiated uterine sarcoma',G,'An exclusion diagnosis after fusion-defined sarcomas.',s='Recurrent — TP53 and other tumor-suppressor lesions (variable)',c='Frequent — complex copy-number changes',p='Exclude high-grade ESS, leiomyosarcoma, rhabdomyosarcoma and molecularly defined sarcomas.',refs='gyn')
e('utrosct','Uterine tumor resembling ovarian sex cord tumor, malignant',G,'UTROSCT → NCOA-family fusions.',r='Characteristic — ESR1::NCOA3; GREB1::NCOA1/2 and related fusions',p='Only malignant/metastasizing cases within scope; a fusion does not itself prove malignant behavior.',refs='gyn')
e('smarcaut','SMARCA4-deficient uterine sarcoma',G,'Undifferentiated uterine sarcoma + SMARCA4 loss.',s='Driver — SMARCA4 inactivation',p='An emerging molecularly defined sarcoma; distinguish from dedifferentiated endometrial carcinoma.',refs='gyn scco')
e('gestchorio','Gestational choriocarcinoma',G,'Gestational origin is shown by parental-genome analysis.',o='Defining context — conceptus-derived trophoblast, often demonstrable paternal alleles',p='No universal recurrent somatic driver. Genotyping distinguishes gestational from nongestational disease; paternal DNA is not an oncogenic gene fusion.',refs='gyn')
e('pstt','Placental site trophoblastic tumor',G,'PSTT: implantation-site trophoblast, no universal genetic driver.',o='Defining context — gestational/conceptus-derived genome',p='Specific recurrent initiating SNV/CNV/fusion not established; rare nongestational trophoblastic tumors need separate context.',refs='gyn',aliases='PSTT')
