e('sinonint','Intestinal-type sinonasal adenocarcinoma',N,'Sinonasal intestinal-type: TP53 and RAS/WNT subsets.',s='Recurrent — TP53, KRAS, APC/CTNNB1 alterations (variable)',p='Exclude metastatic colorectal carcinoma; molecular resemblance is not proof of a common origin.',refs='hn')
