e('onb','Olfactory neuroblastoma',N,'Olfactory neuroblastoma has no single defining genetic driver.',s='Subset — TP53 and chromatin/PI3K-pathway alterations',p='Not the same molecular disease as peripheral neuroblastoma; MYCN amplification is not a universal ONB hallmark.',refs='hn sinonasal',aliases='esthesioneuroblastoma')
e('bsns','Biphenotypic sinonasal sarcoma',N,'Biphenotypic sinonasal sarcoma → PAX3 fusion.',r='Characteristic — PAX3::MAML3; alternative PAX3 partners',p='The fusion partner matters: PAX3::FOXO1 also occurs in rhabdomyosarcoma.',refs='hn')
